namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly object _lock = new();
    private readonly List<Notification> _notifications = new();

    public NotificationService()
    {
        // Seed with some initial fake data.
        Add("Welcome to the app!");
        Add("Your profile was created.");
        Add("You have a new follower.");
    }

    /// <summary>Returns all notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetNotifications(int sinceId = 0)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    private void Add(string message)
    {
        lock (_lock)
        {
            _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
        }
    }

    /// <summary>Simulates a new notification arriving. Called by the background generator.</summary>
    public void GenerateFake()
    {
        string[] templates =
        [
            "New comment on your post",
            "Someone liked your photo",
            "Meeting reminder in 15 minutes",
            "Deployment succeeded",
            "New sign-in from another device",
            "Weekly report is ready",
        ];

        Add(templates[Random.Shared.Next(templates.Length)]);
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// Background service that periodically generates fake notifications
/// so the polling page has something new to pick up.
/// </summary>
public class NotificationGenerator : BackgroundService
{
    private readonly NotificationService _notifications;

    public NotificationGenerator(NotificationService notifications) =>
        _notifications = notifications;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(7), stoppingToken);
            _notifications.GenerateFake();
        }
    }
}

@page "/notifications"
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationsApp.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Highest Id we've seen — used for incremental polling.
    private int _lastSeenId;

    /// <summary>
    /// Runs during the initial static SSR *and* again when the component
    /// becomes interactive.  We only load data on the first call so the
    /// interactive activation reuses what was already rendered.
    /// </summary>
    protected override void OnInitialized()
    {
        if (_notifications.Count == 0)
        {
            _notifications = NotificationSvc.GetNotifications();
            _lastSeenId = _notifications.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;
        }
    }

    /// <summary>
    /// Called only once and only after the component is running interactively
    /// on the server-side SignalR circuit — never during static SSR.
    /// This is the safe place to start the polling loop.
    /// </summary>
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            var newer = NotificationSvc.GetNotifications(_lastSeenId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

