namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly object _lock = new();
    private readonly List<Notification> _notifications = new();

    public NotificationService()
    {
        Add("Welcome to the app!");
        Add("Your profile was created.");
        Add("You have a new follower.");
    }

    /// <summary>Returns all notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetNotifications(int sinceId = 0)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    private void Add(string message)
    {
        lock (_lock)
        {
            _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
        }
    }

    /// <summary>Simulates a new notification arriving. Called by the background generator.</summary>
    public void GenerateFake()
    {
        string[] templates =
        [
            "New comment on your post",
            "Someone liked your photo",
            "Meeting reminder in 15 minutes",
            "Deployment succeeded",
            "New sign-in from another device",
            "Weekly report is ready",
        ];

        Add(templates[Random.Shared.Next(templates.Length)]);
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// Background service that periodically generates fake notifications
/// so the polling page has something new to pick up.
/// </summary>
public class NotificationGenerator : BackgroundService
{
    private readonly NotificationService _notifications;

    public NotificationGenerator(NotificationService notifications) =>
        _notifications = notifications;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(7), stoppingToken);
            _notifications.GenerateFake();
        }
    }
}

